import java.util.*;

public class Solution {
  static final int[] DR = {1, -1, 0, 0}, DC = {0, 0, 1, -1};

  static boolean inside(int[][] a, int r, int c) {
    return r >= 0 && c >= 0 && r < a.length && c < a[0].length;
  }

  static void fill(int[][] a, int r, int c, int original, int replacement) {
    if (!inside(a, r, c) || a[r][c] != original) return;
    a[r][c] = replacement;
    for (int d = 0; d < 4; d++) fill(a, r + DR[d], c + DC[d], original, replacement);
  }

  static int[][] copy(int[][] a) {
    int[][] b = new int[a.length][];
    for (int i = 0; i < a.length; i++) b[i] = a[i].clone();
    return b;
  }

  static void shape(int[][] a, int r, int c, int br, int bc, List<String> p) {
    if (!inside(a, r, c) || a[r][c] != 1) return;
    a[r][c] = 0;
    p.add((r - br) + ":" + (c - bc));
    for (int d = 0; d < 4; d++) shape(a, r + DR[d], c + DC[d], br, bc, p);
  }

  public static int solve(int[][] input) {
    int[][] a = copy(input);
    Set<String> shapes = new HashSet<>();
    for (int r = 0; r < a.length; r++)
      for (int c = 0; c < a[r].length; c++)
        if (a[r][c] == 1) {
          List<String> p = new ArrayList<>();
          shape(a, r, c, r, c, p);
          Collections.sort(p);
          shapes.add(p.toString());
        }
    return shapes.size();
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 1, 0, 1, 1}, {1, 0, 0, 1, 0}}));
  }
}

Detect a cycle in an undirected graph.source:
import java.util.*;

public class Solution {
  static List<List<Integer>> graph(int n, int[][] edges, boolean directed) {
    List<List<Integer>> g = new ArrayList<>();
    for (int i = 0; i < n; i++) g.add(new ArrayList<>());
    for (int[] e : edges) {
      g.get(e[0]).add(e[1]);
      if (!directed) g.get(e[1]).add(e[0]);
    }
    return g;
  }

  static void visit(List<List<Integer>> g, int u, boolean[] seen) {
    seen[u] = true;
    for (int v : g.get(u)) if (!seen[v]) visit(g, v, seen);
  }

  static boolean cycle(List<List<Integer>> g, int u, int parent, boolean[] seen) {
    seen[u] = true;
    boolean skippedParent = false;
    for (int v : g.get(u)) {
      if (v == parent && !skippedParent) {
        skippedParent = true;
        continue;
      }
      if (seen[v] || cycle(g, v, u, seen)) return true;
    }
    return false;
  }

  public static boolean solve(int n, int[][] edges) {
    List<List<Integer>> g = graph(n, edges, false);
    boolean[] seen = new boolean[n];
    for (int i = 0; i < n; i++) if (!seen[i] && cycle(g, i, -1, seen)) return true;
    return false;
  }

  public static void main(String[] args) {
    System.out.println(solve(3, new int[][] {{0, 1}, {1, 2}, {2, 0}}));
  }
}

