import java.util.*;

public class Solution {
  static List<List<Integer>> graph(int n, int[][] edges, boolean directed) {
    List<List<Integer>> g = new ArrayList<>();
    for (int i = 0; i < n; i++) g.add(new ArrayList<>());
    for (int[] e : edges) {
      g.get(e[0]).add(e[1]);
      if (!directed) g.get(e[1]).add(e[0]);
    }
    return g;
  }

  static void visit(List<List<Integer>> g, int u, boolean[] seen) {
    seen[u] = true;
    for (int v : g.get(u)) if (!seen[v]) visit(g, v, seen);
  }

  public static boolean solve(int n, int[][] edges) {
    List<List<Integer>> g = graph(n, edges, false);
    int[] color = new int[n];
    Arrays.fill(color, -1);
    Queue<Integer> q = new ArrayDeque<>();
    for (int start = 0; start < n; start++)
      if (color[start] < 0) {
        color[start] = 0;
        q.offer(start);
        while (!q.isEmpty()) {
          int u = q.poll();
          for (int v : g.get(u)) {
            if (color[v] < 0) {
              color[v] = 1 - color[u];
              q.offer(v);
            } else if (color[v] == color[u]) return false;
          }
        }
      }
    return true;
  }

  public static void main(String[] args) {
    System.out.println(solve(3, new int[][] {{0, 1}, {1, 2}, {2, 0}}));
  }
}

Topological sort or Kahn's algorithm.source:
import java.util.*;

public class Solution {
  static List<List<Integer>> graph(int n, int[][] edges, boolean directed) {
    List<List<Integer>> g = new ArrayList<>();
    for (int i = 0; i < n; i++) g.add(new ArrayList<>());
    for (int[] e : edges) {
      g.get(e[0]).add(e[1]);
      if (!directed) g.get(e[1]).add(e[0]);
    }
    return g;
  }

  static void visit(List<List<Integer>> g, int u, boolean[] seen) {
    seen[u] = true;
    for (int v : g.get(u)) if (!seen[v]) visit(g, v, seen);
  }

  static List<Integer> order(List<List<Integer>> g) {
    int[] degree = new int[g.size()];
    for (List<Integer> row : g) for (int v : row) degree[v]++;
    Queue<Integer> q = new ArrayDeque<>();
    for (int i = 0; i < degree.length; i++) if (degree[i] == 0) q.offer(i);
    List<Integer> out = new ArrayList<>();
    while (!q.isEmpty()) {
      int u = q.poll();
      out.add(u);
      for (int v : g.get(u)) if (--degree[v] == 0) q.offer(v);
    }
    return out;
  }

  public static List<Integer> solve(int n, int[][] edges) {
    List<Integer> result = order(graph(n, edges, true));
    return result.size() == n ? result : Collections.emptyList();
  }

  public static void main(String[] args) {
    System.out.println(solve(4, new int[][] {{0, 1}, {0, 2}, {1, 3}, {2, 3}}));
  }
}

