      if (p[0] != d[u]) continue;
      for (long[] e : g.get(u)) {
        if (e[1] < 0) throw new IllegalArgumentException("nonnegative weights required");
        int v = (int) e[0];
        long next = d[u] + e[1];
        if (next < d[v]) {
          d[v] = next;
          q.offer(new long[] {next, v});
        }
      }
    }
    return d;
  }

  public static long solve(int n, int[][] edges, int source) {
    long[] d = dijkstra(n, edges, source, true);
    long best = 0;
    for (long x : d) {
      if (x == INF) return -1;
      best = Math.max(best, x);
