    }

    int find(int x) {
      while (x != parent[x]) {
        parent[x] = parent[parent[x]];
        x = parent[x];
      }
      return x;
    }

    boolean union(int a, int b) {
      a = find(a);
      b = find(b);
      if (a == b) return false;
      if (size[a] < size[b]) {
        int t = a;
        a = b;
        b = t;
      }
      parent[b] = a;
      size[a] += size[b];
      return true;
    }
  }

  public static int solve(int[][] a) {
    if (a.length == 0 || a[0].length == 0) return 0;
    int m = a.length, n = a[0].length;
    DSU d = new DSU(m * n);
    for (int r = 0; r < m; r++)
      for (int c = 0; c < n; c++)
        if (a[r][c] == 1) {
          if (r + 1 < m && a[r + 1][c] == 1) d.union(r * n + c, (r + 1) * n + c);
          if (c + 1 < n && a[r][c + 1] == 1) d.union(r * n + c, r * n + c + 1);
        }
    int best = 0;
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    for (int r = 0; r < m; r++)
      for (int c = 0; c < n; c++) {
        if (a[r][c] == 1) {
          best = Math.max(best, d.size[d.find(r * n + c)]);
          continue;
        }
        Set<Integer> roots = new HashSet<>();
        for (int k = 0; k < 4; k++) {
          int x = r + dr[k], y = c + dc[k];
          if (x >= 0 && y >= 0 && x < m && y < n && a[x][y] == 1) roots.add(d.find(x * n + y));
        }
        int size = 1;
        for (int root : roots) size += d.size[root];
        best = Math.max(best, size);
      }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 0}, {0, 1}}));
  }
}

Most stones removed with same row or col.source:
import java.util.*;

public class Solution {
  static class DSU {
    final int[] parent, size;

    DSU(int n) {
      parent = new int[n];
      size = new int[n];
      for (int i = 0; i < n; i++) {
        parent[i] = i;
        size[i] = 1;
      }
    }

    int find(int x) {
      while (x != parent[x]) {
        parent[x] = parent[parent[x]];
        x = parent[x];
      }
      return x;
    }

    boolean union(int a, int b) {
      a = find(a);
      b = find(b);
      if (a == b) return false;
      if (size[a] < size[b]) {
        int t = a;
        a = b;
        b = t;
      }
      parent[b] = a;
      size[a] += size[b];
      return true;
    }
  }

  public static int solve(int[][] stones) {
    DSU d = new DSU(stones.length);
    Map<Integer, Integer> row = new HashMap<>(), col = new HashMap<>();
    int components = stones.length;
    for (int i = 0; i < stones.length; i++) {
      Integer a = row.putIfAbsent(stones[i][0], i), b = col.putIfAbsent(stones[i][1], i);
      if (a != null && d.union(i, a)) components--;
      if (b != null && d.union(i, b)) components--;
    }
    return stones.length - components;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{0, 0}, {0, 1}, {1, 0}, {1, 2}, {2, 1}, {2, 2}}));
  }
}

Kosaraju's algorithm.source:
import java.util.*;

public class Solution {
  static List<List<Integer>> graph(int n, int[][] edges, boolean directed) {
    List<List<Integer>> g = new ArrayList<>();
    for (int i = 0; i < n; i++) g.add(new ArrayList<>());
    for (int[] e : edges) {
      g.get(e[0]).add(e[1]);
      if (!directed) g.get(e[1]).add(e[0]);
    }
    return g;
  }

  static void visit(List<List<Integer>> g, int u, boolean[] seen) {
    seen[u] = true;
    for (int v : g.get(u)) if (!seen[v]) visit(g, v, seen);
  }

  static void finish(List<List<Integer>> g, int u, boolean[] seen, List<Integer> out) {
    seen[u] = true;
    for (int v : g.get(u)) if (!seen[v]) finish(g, v, seen, out);
    out.add(u);
  }

  public static int solve(int n, int[][] edges) {
    List<List<Integer>> g = graph(n, edges, true), rev = graph(n, new int[0][], true);
    for (int[] e : edges) rev.get(e[1]).add(e[0]);
    boolean[] seen = new boolean[n];
    List<Integer> order = new ArrayList<>();
    for (int u = 0; u < n; u++) if (!seen[u]) finish(g, u, seen, order);
    Arrays.fill(seen, false);
    Collections.reverse(order);
    int count = 0;
    for (int u : order)
      if (!seen[u]) {
        count++;
        visit(rev, u, seen);
      }
    return count;
  }

  public static void main(String[] args) {
    System.out.println(solve(4, new int[][] {{0, 1}, {1, 2}, {2, 0}, {2, 3}}));
  }
}

Bridges in graph.source:
import java.util.*;

public class Solution {
  static class Analysis {
    int time;
    final int[] in, low;
    final boolean[] cut;
    final List<List<int[]>> g = new ArrayList<>();
    final List<List<Integer>> bridges = new ArrayList<>();

    Analysis(int n, int[][] edges) {
      in = new int[n];
      low = new int[n];
      cut = new boolean[n];
      Arrays.fill(in, -1);
      for (int i = 0; i < n; i++) g.add(new ArrayList<>());
      for (int id = 0; id < edges.length; id++) {
        int[] e = edges[id];
        g.get(e[0]).add(new int[] {e[1], id});
        g.get(e[1]).add(new int[] {e[0], id});
      }
      for (int u = 0; u < n; u++) if (in[u] < 0) dfs(u, -1);
    }

    void dfs(int u, int parentEdge) {
      in[u] = low[u] = time++;
      int children = 0;
      for (int[] e : g.get(u)) {
        int v = e[0];
        if (e[1] == parentEdge) continue;
        if (in[v] >= 0) low[u] = Math.min(low[u], in[v]);
        else {
          children++;
          dfs(v, e[1]);
          low[u] = Math.min(low[u], low[v]);
          if (low[v] > in[u]) bridges.add(Arrays.asList(Math.min(u, v), Math.max(u, v)));
          if (parentEdge != -1 && low[v] >= in[u]) cut[u] = true;
        }
      }
      if (parentEdge == -1 && children > 1) cut[u] = true;
    }
  }

  public static List<List<Integer>> solve(int n, int[][] edges) {
    List<List<Integer>> out = new Analysis(n, edges).bridges;
    out.sort(
        (a, b) ->
            a.get(0).equals(b.get(0))
                ? Integer.compare(a.get(1), b.get(1))
                : Integer.compare(a.get(0), b.get(0)));
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve(4, new int[][] {{0, 1}, {1, 2}, {2, 0}, {2, 3}}));
  }
}

