import java.util.*;

public class Solution {
  static List<List<Integer>> graph(int n, int[][] edges, boolean directed) {
    List<List<Integer>> g = new ArrayList<>();
    for (int i = 0; i < n; i++) g.add(new ArrayList<>());
    for (int[] e : edges) {
      g.get(e[0]).add(e[1]);
      if (!directed) g.get(e[1]).add(e[0]);
    }
    return g;
  }

  static void visit(List<List<Integer>> g, int u, boolean[] seen) {
    seen[u] = true;
    for (int v : g.get(u)) if (!seen[v]) visit(g, v, seen);
  }

  static void dfs(List<List<Integer>> g, int u, boolean[] seen, List<Integer> out) {
    seen[u] = true;
    out.add(u);
    for (int v : g.get(u)) if (!seen[v]) dfs(g, v, seen, out);
  }

  public static List<Integer> solve(int n, int[][] edges) {
    List<List<Integer>> g = graph(n, edges, false);
    boolean[] seen = new boolean[n];
    List<Integer> out = new ArrayList<>();
    for (int u = 0; u < n; u++) if (!seen[u]) dfs(g, u, seen, out);
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve(4, new int[][] {{0, 1}, {0, 2}, {1, 3}}));
  }
}

Number of Islands with Eight Directions.source:
import java.util.*;

public class Solution {
  static final int[] DR = {1, -1, 0, 0}, DC = {0, 0, 1, -1};

  static boolean inside(int[][] a, int r, int c) {
    return r >= 0 && c >= 0 && r < a.length && c < a[0].length;
  }

  static void fill(int[][] a, int r, int c, int original, int replacement) {
    if (!inside(a, r, c) || a[r][c] != original) return;
    a[r][c] = replacement;
    for (int d = 0; d < 4; d++) fill(a, r + DR[d], c + DC[d], original, replacement);
  }

  static int[][] copy(int[][] a) {
    int[][] b = new int[a.length][];
    for (int i = 0; i < a.length; i++) b[i] = a[i].clone();
    return b;
  }

  static void eight(int[][] a, int r, int c) {
    if (!inside(a, r, c) || a[r][c] != 1) return;
    a[r][c] = 0;
    for (int dr = -1; dr <= 1; dr++)
      for (int dc = -1; dc <= 1; dc++) if (dr != 0 || dc != 0) eight(a, r + dr, c + dc);
  }

  public static int solve(int[][] input) {
    int[][] a = copy(input);
    int count = 0;
    for (int r = 0; r < a.length; r++)
      for (int c = 0; c < a[r].length; c++)
        if (a[r][c] == 1) {
          count++;
          eight(a, r, c);
        }
    return count;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 0}, {0, 1}}));
  }
}
